"""V22: guarded collection recovery, independent manager settlement and display retention."""
import argparse, ast, copy, textwrap, base64, fcntl, hashlib, io, json, os, subprocess, sys, tempfile, time, zipfile
from pathlib import Path
ARCHIVE=''

def sha(raw): return hashlib.sha256(raw).hexdigest()
def read(p): return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def payload():
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(ARCHIVE))) as z:
        return {n:z.read(n) for n in z.namelist()}
def atomic(p,raw):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True)
    mode=p.stat().st_mode&0o777 if p.exists() else 0o600
    fd,tmp=tempfile.mkstemp(dir=p.parent,prefix='.v22-')
    try:
        with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
        os.chmod(tmp,mode);os.replace(tmp,p)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def same(a,b): return ast.dump(a,include_attributes=False)==ast.dump(b,include_attributes=False)

def patch_source(raw, name, spec):
    text=raw.decode('utf-8-sig'); tree=ast.parse(text)
    nodes={n.name:n for n in tree.body if isinstance(n,ast.FunctionDef)}
    lines=text.splitlines(keepends=True);nl='\r\n' if b'\r\n' in raw else '\n'
    changes=[]; added=[]
    for function, change in spec.get('functions',{}).items():
        if function not in nodes:
            if change.get('new'):
                added.append(change['after']);continue
            raise ValueError(name+' 함수 없음: '+function+' · 변경 없음')
        node=nodes[function]; after=ast.parse(change['after']).body[0]
        if same(node,after): continue
        if change.get('new') or not any(same(node,ast.parse(source).body[0]) for source in change['before']):
            raise ValueError(name+' 대상 함수 버전 불일치: '+function+' · 변경 없음')
        changes.append((node,change['after']))
    for class_name, methods in spec.get('methods',{}).items():
        cls=next((n for n in tree.body if isinstance(n,ast.ClassDef) and n.name==class_name),None)
        if cls is None:raise ValueError(name+' 클래스 없음: '+class_name+' · 변경 없음')
        for method,change in methods.items():
            node=next((n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name==method),None)
            if node is None:raise ValueError(name+' 메서드 없음: '+class_name+'.'+method)
            after=ast.parse(change['after']).body[0]
            if same(node,after):continue
            if node.decorator_list or not any(same(node,ast.parse(v).body[0]) for v in change['before']):
                raise ValueError(name+' 대상 메서드 버전 불일치: '+class_name+'.'+method+' · 변경 없음')
            changes.append((node,textwrap.indent(change['after'].rstrip(),' '*node.col_offset)))
    for function, anchors in spec.get('anchors',{}).items():
        node=nodes[function]; segment=ast.get_source_segment(text,node).replace('\r\n','\n')
        for old,new in anchors:
            if segment.count(new)==1: continue
            if segment.count(old)!=1:raise ValueError(name+' 연결 위치 확인 필요: '+function+' · 변경 없음')
            segment=segment.replace(old,new)
        if segment!=ast.get_source_segment(text,node).replace('\r\n','\n'):changes.append((node,segment))
    for node, source in sorted(changes,key=lambda pair:pair[0].lineno,reverse=True):
        lines[node.lineno-1:node.end_lineno]=[source.replace('\r\n','\n').replace('\n',nl)+nl]
    value=''.join(lines)
    if added:
        parsed=ast.parse(value); guard=next((n for n in parsed.body if isinstance(n,ast.If) and '__name__' in ast.unparse(n.test) and '__main__' in ast.unparse(n.test)),None)
        insertion=nl+nl+(nl+nl).join(s.replace('\n',nl) for s in added)+nl+nl
        if guard:
            ls=value.splitlines(keepends=True);ls.insert(guard.lineno-1,insertion);value=''.join(ls)
        else:value+=insertion
    for name in spec.get('before_main',[]):
        parsed=ast.parse(value);guard=next((n for n in parsed.body if isinstance(n,ast.If) and '__name__' in ast.unparse(n.test) and '__main__' in ast.unparse(n.test)),None)
        fn=next((n for n in parsed.body if isinstance(n,ast.FunctionDef) and n.name==name),None)
        if guard and fn and fn.lineno>guard.lineno:
            ls=value.splitlines(keepends=True);source=''.join(ls[fn.lineno-1:fn.end_lineno]);del ls[fn.lineno-1:fn.end_lineno]
            ls.insert(guard.lineno-1,source+nl+nl);value=''.join(ls)
    result=value.encode()
    if raw.startswith(b'\xef\xbb\xbf'):result=b'\xef\xbb\xbf'+result
    actual=ast.parse(result.decode('utf-8-sig'))
    edited=set(spec.get('functions',{}))|set(spec.get('anchors',{}))
    def untouched(parsed):
        result=[]
        for node in parsed.body:
            if isinstance(node,ast.FunctionDef) and node.name in edited:continue
            node=copy.deepcopy(node)
            if isinstance(node,ast.ClassDef) and node.name in spec.get('methods',{}):
                methods=spec['methods'][node.name]
                node.body=[m for m in node.body if not(isinstance(m,ast.FunctionDef) and m.name in methods)]
            result.append(ast.dump(node,include_attributes=False))
        return result
    if untouched(tree)!=untouched(actual):raise ValueError(name+' 수정 대상 외 변경 감지')
    compile(result.decode('utf-8-sig'),name,'exec')
    return result

class GitHub:
    def __init__(self,root):
        sys.path.insert(0,str(root))
        from manager_investment_publish import _settings
        import requests
        repo,token=_settings()
        if repo!='chleowhd77-ops/-':raise ValueError('대상 GitHub 저장소 확인 필요 · 변경 없음')
        self.requests=requests;self.base='https://api.github.com/repos/'+repo
        self.headers={'Authorization':'token '+token,'Accept':'application/vnd.github+json'}
    def request(self,method,path,body=None):
        r=self.requests.request(method,self.base+path,headers=self.headers,json=body,timeout=30)
        if not 200<=r.status_code<300:raise RuntimeError('GitHub '+method+' '+path+' HTTP '+str(r.status_code))
        return r.json()
    def prepare(self,files,specs):
        allowed=json.loads(payload()['helper_allowed.json'])
        self.base_commit=self.request('GET','/git/ref/heads/main')['object']['sha']
        self.base_tree=self.request('GET','/git/commits/'+self.base_commit)['tree']['sha']
        entries=self.request('GET','/git/trees/'+self.base_tree)['tree']
        self.entries={v['path']:v for v in entries}
        self.old={};self.new={}
        for name,raw in files.items():
            entry=self.entries.get(name)
            if entry:
                item=self.request('GET','/git/blobs/'+entry['sha'])
                if item.get('encoding')!='base64':raise ValueError('GitHub 원문 인코딩 확인 필요')
                prior=base64.b64decode(item['content']);self.old[name]=prior
                if name in specs:
                    raw=patch_source(prior,name,specs[name])
                elif prior!=raw and sha(prior) not in allowed.get(name,[]):raise ValueError('GitHub에 다른 도우미 파일 있음: '+name+' · 변경 없음')
            else:
                if name in specs:raise ValueError('GitHub 기존 소스 없음: '+name)
                self.old[name]=None
            if raw!=self.old[name]:self.new[name]=raw
        return self.new
    def commit(self):
        if not self.new:return None
        if self.request('GET','/git/ref/heads/main')['object']['sha']!=self.base_commit:
            raise ValueError('확인 중 GitHub main 변경 · 다시 확인 필요')
        entries=[]
        for name,raw in self.new.items():
            blob=self.request('POST','/git/blobs',{'content':base64.b64encode(raw).decode(),'encoding':'base64'})
            entries.append({'path':name,'mode':'100644','type':'blob','sha':blob['sha']})
        tree=self.request('POST','/git/trees',{'base_tree':self.base_tree,'tree':entries})
        commit=self.request('POST','/git/commits',{'message':'Fix team search, live-error study and collection coverage (V23)','tree':tree['sha'],'parents':[self.base_commit]})
        self.committed=commit['sha']
        # Non-force update never overwrites another person's intervening commit.
        self.request('PATCH','/git/refs/heads/main',{'sha':self.committed,'force':False})
        self.updated=True
        return self.committed
    def rollback(self):
        if not getattr(self,'committed',None):return
        current=self.request('GET','/git/ref/heads/main')['object']['sha']
        if current==self.base_commit:return
        if current!=self.committed:
            raise RuntimeError('GitHub main에 후속 변경 있음 · 자동 되돌림 보류')
        previous=[]
        for name in self.new:
            previous.append({'path':name,'mode':'100644','type':'blob',
                             'sha':self.entries[name]['sha'] if name in self.entries else None})
        tree=self.request('POST','/git/trees',{'base_tree':self.request('GET','/git/commits/'+self.committed)['tree']['sha'],'tree':previous})
        commit=self.request('POST','/git/commits',{'message':'Rollback incomplete V22 installation','tree':tree['sha'],'parents':[self.committed]})
        self.request('PATCH','/git/refs/heads/main',{'sha':commit['sha'],'force':False})

class Services:
    def state(self,name):
        p=subprocess.run(['systemctl','show',name,'-p','ActiveState','--value'],capture_output=True,text=True)
        return p.stdout.strip() if p.returncode==0 else 'unknown'
    def run(self,*args):subprocess.run(['sudo','-n','systemctl',*args],check=True)

def planned(root,files):
    state=root/'dj-manager-memory/runtime'; active=read(state/'ACTIVATED.json')
    code=Path(active['code']).resolve();code.relative_to((root/'dj-manager-memory/runtime-code').resolve())
    specs=json.loads(files['patches.json']);out={}
    paths={root/'collector.py',root/'api_engine.py',root/'collection_completeness.py',
           root/'manager_material.py',code/'manager_material.py',
           code/'manager_memory_inputs.py',code/'manager_remembered_runtime.py',
           code/'manager_full_coverage.py',code/'manager_practice_bridge.py'}
    for path in paths:
        if path.is_symlink() or not path.is_file():raise ValueError('운영 원본 경로 확인 필요: '+str(path))
        out[path]=patch_source(path.read_bytes(),path.name,specs[path.name])
    allowed=json.loads(files['helper_allowed.json'])
    for directory,names in ((root,('collection_history.py','collection_shared_inputs.py','collection_team_names.py','collection_recovery.py')),
                            (code,('collection_shared_inputs.py','manager_live_review_check.py','manager_collection_context.py','manager_portfolio_identity.py'))):
        for name in names:
            target=directory/name
            if target.is_symlink():raise ValueError('링크 경로 변경 차단')
            if target.exists() and target.read_bytes()!=files[name] and sha(target.read_bytes()) not in allowed.get(name,[]):
                raise ValueError('기존 도우미 버전 확인 필요: '+str(target))
            out[target]=files[name]
    for path,raw in out.items():compile(raw.decode('utf-8-sig'),str(path),'exec')
    return state,code,out,specs

def original_hashes(code):
    base=code/'practice_original';manifest=read(base/'manifest.json');out={}
    for name,meta in manifest.items():
        raw=(base/name).read_bytes()
        if sha(raw)!=meta['sha256']:raise ValueError('원본 모의투자 소스 변경 감지: '+name)
        out[name]=sha(raw)
    return out

def install(root,apply=False,resume=False,services=None,github=None,unit_dir=None):
    files=payload();state,code,out,specs=planned(root,files)
    svc=services or Services()
    github=github or GitHub(root)
    original=original_hashes(code)
    if svc.state('dj-remembered-manager.service') not in ('inactive','failed'):
        raise ValueError('관리자 분석 실행 중 · 저장 답안 보호를 위해 이번 수정 보류')
    pause=state/'PAUSED.json'
    if resume:raise ValueError('V23은 수집 수정만 적용 · 임의 AI 재개 없음')
    remote_names=('collector.py','api_engine.py','manager_material.py','collection_completeness.py','collection_history.py','collection_shared_inputs.py','collection_team_names.py','collection_recovery.py')
    remote=github.prepare({n:(out[root/n] if root/n in out else files[n]) for n in remote_names},specs)
    print('V23 운영 함수·원본 학습·GitHub main 버전·문법 확인 PASS · 아직 변경 없음',flush=True)
    if not apply:return
    with (state/'worker.lock').open('a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        if svc.state('dj-remembered-manager.service') not in ('inactive','failed'):
            raise ValueError('관리자 분석 시작 감지 · 수정 보류')
        previous={p:p.read_bytes() if p.exists() else None for p in out}
        changed={p:v for p,v in out.items() if previous[p]!=v}
        backup=state/'deployments'/('collection-material-v23-'+str(time.time_ns()))
        backup.mkdir(parents=True,mode=0o700)
        atomic(backup/'V23_CHANGE_REPORT_KO.txt',files['V23_CHANGE_REPORT_KO.txt'])
        manifest=[]
        for i,(path,raw) in enumerate(previous.items()):
            name=f'{i:02d}-{path.name}.before'
            if raw is not None:atomic(backup/name,raw)
            manifest.append({'path':str(path),'backup':name if raw is not None else None,'sha256':sha(raw) if raw is not None else None})
        atomic(backup/'manifest.json',json.dumps(manifest,ensure_ascii=False,indent=2).encode())
        atomic(backup/'github-main.json',json.dumps({'commit':github.base_commit,'tree':github.base_tree}).encode())
        for name,raw in github.old.items():
            if raw is not None:atomic(backup/('github-'+name+'.before'),raw)
        pause_raw=pause.read_bytes() if pause.exists() else None
        if pause_raw is not None:atomic(backup/'PAUSED.before.json',pause_raw)
        timer='dj-remembered-manager.timer';collector='dj-collector.service';settler='dj-manager-settlement.timer'
        running={n:svc.state(n)=='active' for n in (timer,collector,settler)}
        unitdir=Path(unit_dir or '/etc/systemd/system');unit_names=('dj-manager-settlement.service','dj-manager-settlement.timer')
        unit_old={n:(unitdir/n).read_bytes() if (unitdir/n).exists() else None for n in unit_names}
        service=f'''[Unit]\nDescription=DJ local manager settlement without AI\nAfter=network-online.target\n[Service]\nType=oneshot\nUser=ubuntu\nWorkingDirectory={root}\nExecStart={sys.executable} -u {root}/manager_settlement.py --root {root}\nEnvironment=PYTHONUNBUFFERED=1\nTimeoutStartSec=240\n'''
        timertext='[Unit]\nDescription=DJ independent manager settlement timer\n[Timer]\nOnActiveSec=30\nOnUnitInactiveSec=180\nAccuracySec=10\nUnit=dj-manager-settlement.service\n[Install]\nWantedBy=timers.target\n'
        units={'dj-manager-settlement.service':service.encode(),'dj-manager-settlement.timer':timertext.encode()}
        for name,raw in unit_old.items():
            if raw is not None:atomic(backup/(name+'.before'),raw)
        installed_units=False;completed=False
        try:
            for name in (timer,settler,collector):
                if running[name]:svc.run('stop',name)
            if (unitdir/'dj-manager-settlement.service').exists():
                svc.run('stop','dj-manager-settlement.service')
            if svc.state('dj-remembered-manager.service') not in ('inactive','failed'):raise ValueError('관리자 실행 상태 변경 · 수정 보류')
            for path,raw in previous.items():
                if (path.read_bytes() if path.exists() else None)!=raw:raise ValueError('확인 중 운영 파일 변경: '+path.name)
            for path,raw in changed.items():atomic(path,raw)
            installed_units=True
            for name,raw in units.items():
                temp=backup/name;atomic(temp,raw)
                subprocess.run(['sudo','-n','install','-m','644',str(temp),str(unitdir/name)],check=True)
            installed_units=True
            svc.run('daemon-reload')
            if original_hashes(code)!=original:raise ValueError('원본 학습 소스 보존 검증 실패')
            for path,raw in out.items():
                if path.read_bytes()!=raw:raise ValueError('설치 후 소스 검증 실패: '+path.name)
            commit=github.commit()
            atomic(backup/'installed.json',json.dumps({'files':{str(p):sha(v) for p,v in out.items()},'GitHub_main_commit':commit,'AI_requests_during_install':0,'original_practice_preserved':original,'resume_requested':resume},ensure_ascii=False,indent=2).encode())
            # Resume only after all local/remote code has been verified.
            if resume and pause.exists():
                if pause.read_bytes()!=pause_raw:raise ValueError('중단 기록 변경 · 자동 재개 보류')
                os.replace(pause,backup/'PAUSED.resumed.json')
            svc.run('enable','--now',settler)
            completed=True
        except BaseException:
            for path in reversed(list(changed)):
                if previous[path] is None:
                    if path.exists():path.unlink()
                else:atomic(path,previous[path])
            if pause_raw is not None and not pause.exists():atomic(pause,pause_raw)
            if installed_units:
                for name,raw in unit_old.items():
                    if raw is None:subprocess.run(['sudo','-n','rm','-f',str(unitdir/name)],check=True)
                    else:
                        temp=backup/(name+'.rollback');atomic(temp,raw)
                        subprocess.run(['sudo','-n','install','-m','644',str(temp),str(unitdir/name)],check=True)
                svc.run('daemon-reload')
            github.rollback()
            raise
        finally:
            for name in (collector,timer,settler):
                if running[name]:svc.run('start',name)
        print('V23 적용 완료 · DB/동결픽/기억 보존 · 백업: '+str(backup),flush=True)
        print('수집 재시도 우회 방지 · 과거 원본통계 최신순/공정복구 · 실제 리그 제공범위 확인 · 수신자료 전달',flush=True)
        print('설치 자체 AI 요청 0회 · 기존 수집 예산/채점 타이머 유지 · 원본 모의투자/화면 변경 없음',flush=True)
    if completed:
        svc.run('start','--no-block','dj-manager-settlement.service')
        if resume:
            svc.run('reset-failed','dj-remembered-manager.service')
            svc.run('start','--no-block','dj-remembered-manager.service')
            print('현재 경기 관리자 분석 재개 요청 · 미완료/실제 자료 변경 분석과 필요한 복기는 크레딧을 사용함',flush=True)

def wait_and_install(root, apply, wait_seconds, services=None):
    svc=services or Services();deadline=time.monotonic()+max(0,wait_seconds)
    while True:
        try:
            if svc.state('dj-remembered-manager.service') not in ('inactive','failed'):
                raise ValueError('관리자 분석 실행 중 · 저장 답안 보호를 위해 이번 수정 보류')
            return install(root,apply,False,services=svc)
        except (ValueError,BlockingIOError) as error:
            eligible=isinstance(error,BlockingIOError) or str(error).startswith(('관리자 분석 실행 중','관리자 분석 시작 감지'))
            if not eligible or time.monotonic()>=deadline:raise
            print('[수집 수정 적용 대기] 진행 중 분석 종료를 기다립니다 · 강제중단/파일변경 없음',flush=True)
            time.sleep(min(15,max(0,deadline-time.monotonic())))

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--root',type=Path,default=Path('/home/ubuntu'))
    parser.add_argument('--apply',action='store_true')
    parser.add_argument('--wait-idle',type=int,default=0)
    args=parser.parse_args()
    wait_and_install(args.root.resolve(),args.apply,args.wait_idle)
if __name__=='__main__':main()
